package com.campusconnect.model;
import java.time.*;
public class Event { private int id,capacity,registeredCount; private String name,description,venue,organizer; private LocalDate date; private LocalTime time;
 public Event(){} public int getId(){return id;} public void setId(int v){id=v;} public int getCapacity(){return capacity;} public void setCapacity(int v){capacity=v;} public int getRegisteredCount(){return registeredCount;} public void setRegisteredCount(int v){registeredCount=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getVenue(){return venue;} public void setVenue(String v){venue=v;} public String getOrganizer(){return organizer;} public void setOrganizer(String v){organizer=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public LocalTime getTime(){return time;} public void setTime(LocalTime v){time=v;}}
